<script setup>
import{computed,onBeforeUnmount,onMounted,ref}from'vue';import{api}from'../services/api';import{BrainCircuit,Database,ShieldCheck,ArrowUpRight}from'lucide-vue-next';import TeamLogo from'../components/team/TeamLogo.vue'
const report=ref(),loading=ref(true);let refreshTimer
const load=async()=>{try{report.value=await api.model()}finally{loading.value=false}}
onMounted(()=>{load();refreshTimer=window.setInterval(load,60000)})
onBeforeUnmount(()=>window.clearInterval(refreshTimer))
const tiers=computed(()=>(report.value?.selective_accuracy||[]).filter(t=>t.minimum_probability<=.75))
const ledger=computed(()=>report.value?.completed_predictions||{games:[],evaluated:0,correct:0,accuracy:null})
const gameDate=value=>new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',timeZone:'America/New_York'}).format(new Date(value))
const lockTime=value=>new Intl.DateTimeFormat('en-US',{hour:'numeric',minute:'2-digit',timeZone:'America/New_York',timeZoneName:'short'}).format(new Date(value))
const groups=[
  {title:'Team baseline',summary:'Long-horizon quality and whether the record is supported by runs scored and allowed.',features:['Elo rating','Season win percentage','Pythagorean expected record']},
  {title:'Recent results',summary:'Several windows prevent one hot or cold week from dominating the forecast.',features:['Last 5 win rate','Last 10 win rate','Last 20 win rate','Last 10 run margin','Last 20 run margin']},
  {title:'Rolling production',summary:'Current offensive output and run prevention, measured before the matchup.',features:['Rolling runs scored','Rolling runs allowed']},
  {title:'Schedule and venue',summary:'Situational performance without using sportsbook or market information.',features:['Home/road split','Team rest difference']},
  {title:'Starter fundamentals',summary:'Traditional starter quality, track record and readiness.',features:['Starter Elo','Starter rest','Starter ERA','Starter WHIP']},
  {title:'Starter Statcast',summary:'Leakage-safe pitch and contact quality from prior starts only.',features:['Expected wOBA allowed','Hard-hit suppression','Barrel suppression','Whiff rate','Strikeout-minus-walk rate','Velocity profile','Sample reliability','Prior-start history depth']},
  {title:'Lineup and bullpen',summary:'Confirmed or projected personnel plus recent relief workload.',features:['Lineup OPS composition','Bullpen pitches · prior 3 days']},
  {title:'Game environment',summary:'Official venue forecast at expected game time.',features:['Temperature','Wind speed']},
  {title:'Input reliability',summary:'Tells the model how much official matchup context is actually available.',features:['Live context availability']},
]
</script>
<style scoped>
.model-page .model-grid{grid-template-columns:1.15fr .85fr;align-items:start}.factor-intro{font-size:9px;line-height:1.55;color:var(--muted);margin:0 0 14px}.factor-intro b{color:var(--text)}.model-grid .feature-group{padding:14px 0}.feature-group header{display:flex;align-items:center;justify-content:space-between;gap:10px}.feature-group header b{font-size:11px}.feature-group header em{font:600 6px 'DM Mono';font-style:normal;color:var(--acid)}.model-grid .feature-group p{font-size:8px;line-height:1.45;margin:5px 0 8px}.factor-tags{display:flex;flex-wrap:wrap;gap:4px}.factor-tags span{padding:4px 6px;background:var(--wash);font:600 6px 'DM Mono';color:var(--text)}@media(max-width:850px){.model-page .model-grid{grid-template-columns:1fr}}
</style>
<template><div v-if="report" class="model-page"><section class="model-hero"><div><span class="eyebrow">NINTH / MODEL LAB</span><h1>Know what the<br><i>model knows.</i></h1><p>A transparent view of training data, real out-of-sample results, confidence tiers, and the stricter recent-season audit.</p></div><div class="hero-score"><BrainCircuit :size="28"/><small>WALK-FORWARD ACCURACY</small><strong class="mono">{{(report.walk_forward.accuracy*100).toFixed(1)}}%</strong><span>2022–{{report.training_through_season}} · {{report.walk_forward.games.toLocaleString()}} picks</span></div></section><section class="model-stats"><div><Database/><span>TRAINING GAMES</span><strong class="mono">{{report.deployment_training_games.toLocaleString()}}</strong></div><div><ShieldCheck/><span>RECENT OUTER TEST</span><strong class="mono">{{((report.recent_outer?.accuracy||report.accuracy)*100).toFixed(1)}}%</strong></div><div><BrainCircuit/><span>QUALIFIED ACCURACY</span><strong class="mono">{{((report.qualified_accuracy||0)*100).toFixed(1)}}%</strong></div><div><BrainCircuit/><span>BRIER SCORE</span><strong class="mono">{{report.walk_forward.brier_score.toFixed(3)}}</strong></div></section><section class="model-grid"><article><header><span class="eyebrow">SELECTIVITY CURVE</span><h2>Confidence earns its name.</h2><p>Accuracy rises when the model is allowed to pass on weak matchups. Coverage shows how rarely each threshold occurs.</p></header><div class="tier" v-for="tier in tiers" :key="tier.minimum_probability"><div><b class="mono">{{Math.round(tier.minimum_probability*100)}}%+</b><span>displayed win probability</span></div><strong class="mono">{{(tier.accuracy*100).toFixed(1)}}%</strong><div class="bar"><i :style="{width:`${tier.accuracy*100}%`}"></i></div><small>{{tier.games.toLocaleString()}} games / {{(tier.coverage*100).toFixed(1)}}% coverage</small></div></article><aside><span class="eyebrow">ALL DEPLOYED SIGNALS</span><h2>What moves a projection.</h2><p class="factor-intro"><b>{{report.selected_features?.length||report.features?.length||29}} model features</b> grouped below. The matchup page shows only the strongest contributors for that specific game.</p><div v-for="(group,index) in groups" :key="group.title" class="feature-group"><span class="mono">{{String(index+1).padStart(2,'0')}}</span><div><header><b>{{group.title}}</b><em>{{group.features.length}} SIGNALS</em></header><p>{{group.summary}}</p><div class="factor-tags"><span v-for="feature in group.features" :key="feature">{{feature}}</span></div></div></div></aside></section><section class="prediction-ledger"><header><div><span class="eyebrow">LIVE DEPLOYMENT RECORD</span><h2>Finished predictions.</h2><p>Only projections archived before first pitch are eligible. Every result is joined to the official MLB final and cannot be rewritten afterward.</p></div><div class="ledger-score"><small>RUNNING ACCURACY</small><strong class="mono">{{ledger.accuracy===null?'—':`${(ledger.accuracy*100).toFixed(1)}%`}}</strong><span>{{ledger.correct}} correct / {{ledger.evaluated}} evaluated</span></div></header><div v-if="ledger.games.length" class="result-list"><RouterLink v-for="result in ledger.games" :key="result.game_id" :to="`/games/${result.game_id}`" class="result-row"><time class="mono">{{gameDate(result.starts_at)}}</time><div class="result-match"><span><TeamLogo :team="result.away" :size="34"/><b>{{result.away.name}}</b></span><strong class="mono">{{result.away_score}}–{{result.home_score}}</strong><span class="home"><b>{{result.home.name}}</b><TeamLogo :team="result.home" :size="34"/></span></div><div class="result-pick"><small>LOCKED MODEL PICK</small><b>{{result.projected_team.name}} · {{((result.projected_side==='home'?result.home_win_probability:result.away_win_probability)*100).toFixed(1)}}%</b><span>Snapshot {{lockTime(result.snapshot_at)}}</span></div><em :class="result.correct?'correct':'missed'">{{result.correct?'CORRECT':'MISSED'}}</em></RouterLink></div><div v-else class="ledger-empty">Completed predictions will appear after a game with a valid pre-first-pitch snapshot reaches an official final.</div><footer>{{ledger.snapshot_rule}} · refreshes every 60 seconds</footer></section><section class="next-step"><span class="eyebrow">V3 / PRACTICAL PROMOTION</span><h2>Pitch-level starter quality is live.</h2><p>V3 adds leakage-safe prior-start Statcast history and a capped run-margin objective. It meets the 57% all-game and 60% qualified targets; the separate recent outer test remains visible because this is decision support, not a guarantee.</p><a href="https://baseballsavant.mlb.com/en/statcast_search" target="_blank">BASEBALL SAVANT SOURCE <ArrowUpRight :size="14"/></a></section></div><div v-else class="state">{{loading?'LOADING MODEL AUDIT…':'MODEL REPORT UNAVAILABLE'}}</div></template>
