{font-size:11px}.feature-group p{font-size:9px;color:var(--muted);line-height:1.5;margin:5px 0}.prediction-ledger{padding:48px 0;border-bottom:1px solid var(--line)}.prediction-ledger>header{display:flex;align-items:end;justify-content:space-between;gap:30px;margin-bottom:24px}.prediction-ledger header p{max-width:650px;margin:0;font-size:10px;line-height:1.6;color:var(--muted)}.ledger-score{min-width:220px;padding:15px 17px;background:var(--contrast);color:var(--on-contrast);display:grid}.ledger-score small{font:7px 'DM Mono';color:#9da39a}.ledger-score strong{font-size:32px;color:var(--accent);margin:7px 0 3px}.ledger-score span{font:7px 'DM Mono';color:#9da39a}.result-list{border:1px solid var(--line);background:var(--surface)}.result-row{min-height:82px;display:grid;grid-template-columns:62px minmax(330px,1.2fr) minmax(220px,.8fr) 85px;align-items:center;gap:15px;padding:11px 15px;border-bottom:1px solid var(--line);text-decoration:none}.result-row:last-child{border-bottom:0}.result-row:hover{background:var(--wash)}.result-row time{font-size:8px;color:var(--muted);text-transform:uppercase}.result-match{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);align-items:center;gap:10px}.result-match>span{min-width:0;display:flex;align-items:center;gap:8px}.result-match>span.home{justify-content:flex-end;text-align:right}.result-match b{font-size:9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.result-match>strong{font-size:16px}.result-pick{display:grid;gap:3px}.result-pick small{font:6px 'DM Mono';color:var(--muted)}.result-pick b{font-size:10px}.result-pick span{font-size:7px;color:var(--muted)}.result-row>em{justify-self:end;padding:7px 9px;border:1px solid currentColor;font:800 7px 'DM Mono';font-style:normal}.result-row>em.correct{color:var(--acid)}.result-row>em.missed{color:var(--orange)}.ledger-empty{padding:32px;border:1px solid var(--line);color:var(--muted);font-size:10px;text-align:center}.prediction-ledger>footer{margin-top:10px;font:7px 'DM Mono';color:var(--muted)}.next-step{padding:55px 0;max-width:900px}.next-step>p{font-size:13px;line-height:1.8;color:var(--muted)}.next-step a{display:inline-flex;gap:7px;align-items:center;margin-top:12px;padding:12px;background:var(--ink);color:var(--paper);font:600 8px 'DM Mono';text-decoration:none}.state{padding:90px;text-align:center;font:9px 'DM Mono'}@media(max-width:900px){.result-row{grid-template-columns:52px 1fr auto}.result-pick{grid-column:2}.result-row>em{grid-column:3;grid-row:1/3}.result-match{grid-template-columns:1fr auto 1fr}}@media(max-width:850px){.model-hero{grid-template-columns:1fr;padding:40px 0}.hero-score{height:250px}.model-grid{grid-template-columns:1fr}.model-stats{grid-template-columns:repeat(2,1fr)}.model-stats>div:nth-child(2){border-right:0}.prediction-ledger>header{align-items:stretch;flex-direction:column}.ledger-score{width:100%}}@media(max-width:600px){.result-row{grid-template-columns:1fr auto}.result-row time{grid-column:1}.result-match{grid-column:1/-1;grid-row:2}.result-pick{grid-column:1}.result-row>em{grid-column:2;grid-row:3}.result-match b{display:none}}@media(max-width:520px){h1{font-size:56px}.model-hero{gap:20px}.hero-score strong{font-size:55px}.model-stats>div{padding:16px}.model-grid{padding:33px 0}}</style>
